var t=`0402-cornish-pasty`;var o=`world-0402`;var i=`GB`;var r=`northern-europe`;var a=4;var u=92;var l={en:`Cornish Pasty`,ua:`Корнуольський пиріжок`};var s={en:`A traditional dish from United Kingdom, centered on all-purpose flour, beef chuck, potato, turnip. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Велика Британія. Основні складники: пшеничне борошно універсальне, яловича лопатка, картопля, ріпа. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 15 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 15 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:15,i:[[`all-purpose-flour`,500,`g`],[`unsalted-butter`,190,`g`],[`water`,165,`ml`],[`table-salt`,7,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`beef-chuck`,420,`g`],[`potato`,350,`g`],[`turnip`,180,`g`],[`yellow-onion`,150,`g`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Cut pastry into rounds, put raw finely diced beef, potato, turnip and onion in each, fold and firmly crimp the edges.`,ua:`Виріжте кружальця тіста, викладіть дрібно нарізану сиру яловичину, картоплю, ріпу та цибулю; складіть навпіл і надійно защипніть краї.`,t:[`rolling-stuffed-food`],m:15,i:[]},{en:`Roast in a preheated 190°C oven for about 50 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 50 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:50,i:[[`chicken-egg`,1,`pcs`]]}];var g={slug:t,id:o,country:`GB`,region:r,servings:4,minutes:92,title:l,text:s,steps:d};export{i as country,g as default,o as id,u as minutes,r as region,a as servings,t as slug,d as steps,s as text,l as title};